mapper.select:
select s.reservation_id as reservationId, r.reservation_no as reservationNo, r.lab_id as labId, l.lab_name as labName, r.applicant_user_id as applicantUserId, u.real_name as applicantName, u.credit_score as applicantCreditScore, r.reservation_type as reservationType, r.priority_level as priorityLevel, r.status as status, date_format(s.reservation_date, '%Y-%m-%d') as reservationDate, s.period_id as periodId, p.period_no as periodNo, p.period_name as periodName, date_format(p.start_time, '%H:%i') as startTime, date_format(p.end_time, '%H:%i') as endTime, date_format(r.created_at, '%Y-%m-%d %H:%i:%s') as createdAt from lab_reservation_slot s join lab_reservation r on r.id = s.reservation_id join lab l on l.id = r.lab_id join sys_user u on u.id = r.applicant_user_id join class_period p on p.id = s.period_id where s.slot_status = 1 and r.status in (1, 2, 5) and s.reservation_date = #{date}
and l.department_id = #{departmentId}
order by case r.status when 1 then 1 when 2 then 2 when 5 then 3 else 4 end asc, p.start_time asc, r.priority_level asc, u.credit_score desc, r.created_at asc, r.id asc, p.sort_order asc

select r.reservation_type as name, count(distinct r.id) as count
from lab_reservation r
join lab_reservation_slot s on s.reservation_id = r.id
where 1 = 1

    and s.reservation_date  >=  #{startDate}


    and s.reservation_date  <=  #{endDate}


    and r.lab_id = #{labId}

group by r.reservation_type

select r.status as name, count(distinct r.id) as count
from lab_reservation r
join lab_reservation_slot s on s.reservation_id = r.id
where 1 = 1

    and s.reservation_date  >=  #{startDate}


    and s.reservation_date  <=  #{endDate}


    and r.lab_id = #{labId}

group by r.status

select l.lab_name as name, count(distinct r.id) as count from lab l left join lab_reservation r on l.id = r.lab_id left join lab_reservation_slot s on s.reservation_id = r.id where l.deleted = 0
and l.department_id = #{departmentId}
and l.id = #{labId}
and (r.id is null or s.reservation_date >= #{startDate})
and (r.id is null or s.reservation_date <= #{endDate})
group by l.id, l.lab_name order by count desc, l.id asc

select p.period_name as name, count(*) as count
from lab_reservation_slot s
join lab_reservation r on r.id = s.reservation_id
join class_period p on p.id = s.period_id
where 1 = 1

    and s.reservation_date  >=  #{startDate}


    and s.reservation_date  <=  #{endDate}


    and r.lab_id = #{labId}

group by p.id, p.period_name
order by p.sort_order asc, p.period_no asc

select date_format(s.reservation_date, '%Y-%m-%d') as name, count(distinct r.id) as count from lab_reservation_slot s join lab_reservation r on r.id = s.reservation_id where 1 = 1
and s.reservation_date >= #{startDate}
and s.reservation_date <= #{endDate}
group by s.reservation_date order by s.reservation_date asc

mapper.sql:
from lab_reservation r
join lab l on l.id = r.lab_id
join sys_user u on u.id = r.applicant_user_id
join (
    select s.reservation_id,
           min(timestamp(s.reservation_date, p.start_time)) as first_start_at,
           max(timestamp(s.reservation_date, p.end_time)) as last_end_at
    from lab_reservation_slot s
    join class_period p on p.id = s.period_id
    where s.slot_status = 1
    group by s.reservation_id
) slot on slot.reservation_id = r.id
where l.deleted = 0
  and u.deleted = 0
  and l.department_id = #{departmentId}
  and slot.first_start_at  >=  #{startDate}
  and slot.first_start_at  <  date_add(#{endDate}, interval 1 day)

    and l.lab_type = #{labType}


    and r.lab_id = #{labId}


    and r.status = #{status}


    and r.reservation_type = #{reservationType}

mapper.select:
select r.reservation_no as reservationNo, l.lab_name as labName, coalesce(nullif(l.lab_type, ''), '未分类') as labType, u.real_name as applicantName, u.user_no as userNo, case when exists ( select 1 from sys_user_role ur join sys_role role on role.id = ur.role_id where ur.user_id = u.id and role.role_code in ('TEACHER', 'ROLE_TEACHER') ) then '教师' else '学生' end as userRole, r.reservation_type as reservationType, r.status as status, slot.first_start_at as startTime, slot.last_end_at as endTime, case when exists ( select 1 from user_violation_record v where v.reservation_id = r.id and v.violation_type = 2 ) then 1 else 0 end as lateViolation, case when exists ( select 1 from user_violation_record v where v.reservation_id = r.id and v.violation_type = 1 ) then 1 else 0 end as noShowViolation, r.created_at as createdAt, approver.real_name as approverName, audit.audited_at as auditedAt from lab_reservation r join lab l on l.id = r.lab_id join sys_user u on u.id = r.applicant_user_id join ( select s.reservation_id, min(timestamp(s.reservation_date, p.start_time)) as first_start_at, max(timestamp(s.reservation_date, p.end_time)) as last_end_at from lab_reservation_slot s join class_period p on p.id = s.period_id where s.slot_status = 1 group by s.reservation_id ) slot on slot.reservation_id = r.id left join ( select reservation_id, max(created_at) as audited_at, substring_index(group_concat(audit_user_id order by created_at desc separator ','), ',', 1) as latestAuditUserId from reservation_audit_log where audit_action in (2, 3) group by reservation_id ) audit on audit.reservation_id = r.id left join sys_user approver on approver.id = cast(audit.latestAuditUserId as unsigned) where l.deleted = 0 and u.deleted = 0 and l.department_id = #{departmentId} and slot.first_start_at >= #{startDate} and slot.first_start_at < date_add(#{endDate}, interval 1 day)
and l.lab_type = #{labType}
and r.lab_id = #{labId}
and r.status = #{status}
and r.reservation_type = #{reservationType}
order by slot.first_start_at desc, r.id desc limit #{limit}
